import { Component, Input, OnInit, SimpleChanges } from '@angular/core';
import { factIssues } from '../../../interfaces/fact.interface';
import { CommonModule } from '@angular/common';
import { BadgeComponent } from '../../badge/badge.component';

@Component({
  selector: 'selected-issues',
  standalone: true,
  imports: [CommonModule, BadgeComponent],
  templateUrl: './selected-issues.component.html',
  styleUrl: './selected-issues.component.scss'
})
export class SelectedIssuesComponent implements OnInit {
  @Input() viewmode: string = 'F';
  @Input() issueList: factIssues[] = [];
  gropuIssueList: any = [];

  ngOnChanges(changes: SimpleChanges): void {
      if(changes["issueList"]){
        this.groupIssues()
      }
  }


  ngOnInit() {
    this.groupIssues()
  }

  groupIssues() {
    
    if (this.issueList) {
      const groupedIssueList = Object.values(this.issueList.reduce((acc, item) => {
        const { nICid, cCategory } = item;
        if (!acc[nICid]) {
          acc[nICid] = {
            nICid,
            cCategory,
            sublist: []
          };
        }
        acc[nICid].sublist.push(item);
        return acc;
      }, {}));
      this.gropuIssueList = groupedIssueList
    }
  }

}
